namespace InvoiceLib;

/// <summary>
/// Ambient clock that production code reads instead of DateTimeOffset.UtcNow.
/// In tests, assign <see cref="UtcNowFunc"/> to control the current time.
/// </summary>
public static class Clock
{
    private static readonly Func<DateTimeOffset> Default = () => DateTimeOffset.UtcNow;

    public static Func<DateTimeOffset> UtcNowFunc = Default;

    public static DateTimeOffset UtcNow => UtcNowFunc();

    /// <summary>Resets the clock to real time.</summary>
    public static void Reset() => UtcNowFunc = Default;
}

